#include "mock.h"
struct device{int x;};struct mhi_buf{void *buf;dma_addr_t dma_addr;size_t len;};struct bhi_vec_entry{u64 dma_addr,size;};struct image_info{struct mhi_buf *mhi_buf;struct bhi_vec_entry *bhi_vec;u32 entries;};struct mhi_controller{size_t seg_len;bool img_pre_alloc;struct device *cntrl_dev;};
static void *dma_alloc_attrs(struct device *d,size_t n,dma_addr_t *a,int f,int attrs){void *p=alloc_mem(n);*a=(uintptr_t)p;return p;}
static void dma_free_attrs(struct device *d,size_t n,void *p,dma_addr_t a,int attrs){assert(a==(uintptr_t)p);free_mem(p);}
/* FUNCTIONS */
int main(void){struct mhi_controller c={.seg_len=16};struct image_info *img=NULL;unsigned cases=0;for(int fault=1;fault<=8;fault++){fail_alloc=fault;allocation_call=0;int r=mhi_alloc_bhie_table(&c,&img,49);if(!r){assert(img->entries==5);mhi_free_bhie_table(&c,&img);}else assert(r==-ENOMEM);assert(!allocations&&!img);cases++;}
fail_alloc=0;assert(mhi_alloc_bhie_table(&c,&img,0)==-EINVAL);c.seg_len=0;assert(mhi_alloc_bhie_table(&c,&img,2)==-EINVAL);c.seg_len=16;assert(mhi_alloc_bhie_table(&c,&img,SIZE_MAX)==-EOVERFLOW);c.img_pre_alloc=true;assert(mhi_alloc_bhie_table(&c,&img,16)==-EINVAL);c.img_pre_alloc=false;
u8 fw[128];for(unsigned i=0;i<sizeof(fw);i++)fw[i]=i;for(size_t len=1;len<=128;len++){assert(!mhi_alloc_bhie_table(&c,&img,len));unsigned entries=img->entries;assert(!mhi_firmware_copy(&c,fw,len,img));size_t off=0;for(unsigned n=0;n<entries-1;n++){size_t copy=min(len-off,img->mhi_buf[n].len);assert(!memcmp(img->mhi_buf[n].buf,fw+off,copy));assert(img->bhi_vec[n].size==copy);off+=copy;}
assert(off==len);assert(mhi_firmware_copy(&c,fw,(entries-1)*16+1,img)==-EOVERFLOW);size_t vec_len=img->mhi_buf[entries-1].len;img->mhi_buf[entries-1].len=0;assert(mhi_firmware_copy(&c,fw,len,img)==-EINVAL);img->mhi_buf[entries-1].len=vec_len;c.img_pre_alloc=true;assert(!mhi_alloc_bhie_table(&c,&img,len));assert(mhi_alloc_bhie_table(&c,&img,(entries)*16)==-EINVAL);mhi_free_bhie_table(&c,&img);assert(img);c.img_pre_alloc=false;mhi_free_bhie_table(&c,&img);assert(!allocations&&!img);cases++;}
mhi_free_bhie_table(&c,NULL);printf("{\"allocation_copy_and_reuse_cases\":%u,\"partial_allocations_unwound\":true,\"vector_capacity_checked\":true}\n",cases);}
